//! Build-time constants for the module manifest and language tiers (WP-90).
//!
//! Generated by `cargo xtask modules gen` from the root `features.toml`;
//! do not edit by hand.
//!
//! Included by `fg-core/src/lib.rs`; the root crate's `mod-*` /
//! `lang-*` features forward to fg-core (see the generated root
//! `[features]` section), so the `cfg!` expressions below observe the
//! final build configuration.
//!
//! TODO(WP-90 step 6, WP-10): the interface locale list (`fg-ui`) and the
//! backend message trimming are not wired to these tiers yet.
#![allow(dead_code)]

/// All module ids in display (catalog) order, built or not.
#[rustfmt::skip]
pub const CATALOG_IDS: &[&str] = &[
    "portforward",
    "protoroute",
    "ddns",
    "stun",
    "tailscale",
    "netbird",
    "easytier",
    "frp",
    "cloudflared",
    "ssl",
    "waf",
    "webservice",
    "guard",
    "knock",
    "wol",
    "webterminal",
    "cron",
    "docker",
    "webdav",
    "ftp",
    "smb",
    "filebrowser",
    "storage",
    "notify",
    "perf",
    "nettools",
    "backup",
];

/// Core modules: always compiled, no Cargo switch.
#[rustfmt::skip]
pub const CORE_MODULES: &[&str] = &["portforward", "ssl", "webservice"];

/// Optional module ids in display order. The root crate generates a
/// `mod-<id>` feature (and the `dep:fg-<id>` optional dependency) only
/// for the modules whose crate exists in the workspace.
#[rustfmt::skip]
pub const OPTIONAL_MODULES: &[&str] = &["protoroute", "ddns", "stun", "tailscale", "netbird", "easytier", "frp", "cloudflared", "waf", "guard", "knock", "wol", "webterminal", "cron", "docker", "webdav", "ftp", "smb", "filebrowser", "storage", "notify", "perf", "nettools", "backup"];

/// Whether `id` is compiled into this build: core modules always are;
/// optional modules require their `mod-<id>` feature (forwarded from the
/// root crate, see the generated root `[features]` section).
pub fn built(id: &str) -> bool {
    matches!(id, "portforward" | "ssl" | "webservice")
        || (matches!(id, "protoroute") && cfg!(feature = "mod-protoroute"))
        || (matches!(id, "ddns") && cfg!(feature = "mod-ddns"))
        || (matches!(id, "stun") && cfg!(feature = "mod-stun"))
        || (matches!(id, "tailscale") && cfg!(feature = "mod-tailscale"))
        || (matches!(id, "netbird") && cfg!(feature = "mod-netbird"))
        || (matches!(id, "easytier") && cfg!(feature = "mod-easytier"))
        || (matches!(id, "frp") && cfg!(feature = "mod-frp"))
        || (matches!(id, "cloudflared") && cfg!(feature = "mod-cloudflared"))
        || (matches!(id, "guard") && cfg!(feature = "mod-guard"))
        || (matches!(id, "knock") && cfg!(feature = "mod-knock"))
        || (matches!(id, "webterminal") && cfg!(feature = "mod-webterminal"))
        || (matches!(id, "cron") && cfg!(feature = "mod-cron"))
        || (matches!(id, "webdav") && cfg!(feature = "mod-webdav"))
        || (matches!(id, "filebrowser") && cfg!(feature = "mod-filebrowser"))
        || (matches!(id, "notify") && cfg!(feature = "mod-notify"))
        || (matches!(id, "perf") && cfg!(feature = "mod-perf"))
        || (matches!(id, "nettools") && cfg!(feature = "mod-nettools"))
}

/// All module ids compiled into this build, in display order.
pub fn built_modules() -> Vec<&'static str> {
    CATALOG_IDS.iter().copied().filter(|id| built(id)).collect()
}

/// Locales of the `all` language tier (zh-CN, zh-TW, en, de, es, fr, ja, ko, pt-BR, ru).
#[rustfmt::skip]
pub const LANG_ALL: &[&str] = &["zh-CN", "zh-TW", "en", "de", "es", "fr", "ja", "ko", "pt-BR", "ru"];

/// Locales of the `cjk-en` language tier (zh-CN, zh-TW, en).
#[rustfmt::skip]
pub const LANG_CJK_EN: &[&str] = &["zh-CN", "zh-TW", "en"];

/// Locales of the `zh` language tier (zh-CN).
#[rustfmt::skip]
pub const LANG_ZH: &[&str] = &["zh-CN"];

/// Locales embedded in this build, selected by the language tier feature.
/// Precedence: `lang-zh-cn`, then `lang-cjk-en`, then the default `lang-all`.
pub const LOCALES: &[&str] = if cfg!(feature = "lang-zh-cn") {
    LANG_ZH
} else if cfg!(feature = "lang-cjk-en") {
    LANG_CJK_EN
} else {
    LANG_ALL
};
